export interface Activity {
  id: string;
  ageMonths: number;
  title: string;
  area: string;
  areaKey: 'motor' | 'cognitive' | 'social' | 'language';
  duration: number; // minutos
  stars: number;    // 1-5
  description: string;
  instructions: string; // passos separados por \n
  where: string;
  materials?: string;
  isPremium: boolean;
}

export function getActivitiesForMonth(ageMonths: number): Activity[] {
  return ALL_ACTIVITIES.filter(a => a.ageMonths === ageMonths);
}

/** Retorna [age-1, age, age+1] clampado entre 0 e 24 */
export function getMonthTabs(currentAge: number): number[] {
  const prev = Math.max(0, currentAge - 1);
  const next = Math.min(24, currentAge + 1);
  return Array.from({ length: next - prev + 1 }, (_, i) => prev + i);
}

